     1	import type { Room } from '@prisma/client';
     2	import { prisma } from '../../db/client.js';
     3	import type { CreateRoomInput, UpdateRoomInput } from './schema.js';
     4	
     5	export interface RoomFilter {
     6	  name?: string;
     7	  limit: number;
     8	  offset: number;
     9	}
    10	
    11	export function create(input: CreateRoomInput): Promise<Room> {
    12	  return prisma.room.create({ data: input });
    13	}
    14	
    15	export function findById(id: string): Promise<Room | null> {
    16	  return prisma.room.findUnique({ where: { id } });
    17	}
    18	
    19	export function findByName(name: string): Promise<Room | null> {
    20	  return prisma.room.findUnique({ where: { name } });
    21	}
    22	
    23	export function list(filter: RoomFilter): Promise<[Room[], number]> {
    24	  const where = filter.name ? { name: { contains: filter.name } } : {};
    25	  return prisma.$transaction([
    26	    prisma.room.findMany({
    27	      where,
    28	      take: filter.limit,
    29	      skip: filter.offset,
    30	      orderBy: { name: 'asc' },
    31	    }),
    32	    prisma.room.count({ where }),
    33	  ]);
    34	}
    35	
    36	export function update(id: string, input: UpdateRoomInput): Promise<Room> {
    37	  return prisma.room.update({ where: { id }, data: input });
    38	}
    39	
    40	export function remove(id: string): Promise<Room> {
    41	  return prisma.room.delete({ where: { id } });
    42	}
