     9	import * as repository from './repository.js';
    10	import type { CreateUserInput, ListUsersInput, UpdateUserInput } from './schema.js';
    11	
    12	const MAX_NAME_LENGTH = 120;
    13	
    14	function assertValidEmail(email: string): void {
    15	  if (!email.includes('@') || !email.includes('.')) {
    16	    throw validationFailed('Email is not valid', { email });
    17	  }
    18	}
    19	
    20	function assertValidName(name: string): void {
    21	  if (name.length > MAX_NAME_LENGTH) {
    22	    throw validationFailed('Name is too long', { maxLength: MAX_NAME_LENGTH });
    23	  }
    24	}
    25	
    26	export async function createUser(input: CreateUserInput): Promise<User> {
    27	  assertValidEmail(input.email);
    28	  assertValidName(input.name);
    29	  const existing = await repository.findByEmail(input.email);
    30	  if (existing) {
    31	    throw emailTaken(input.email);
    32	  }
    33	  return repository.create(input);
    34	}
    35	
    36	export async function getUser(id: string): Promise<User> {
    37	  const user = await repository.findById(id);
    38	  if (!user) {
    39	    throw notFound('User');
    40	  }
    41	  return user;
    42	}
    43	
    44	export async function listUsers(query: ListUsersInput): Promise<Page<User>> {
    45	  const limit = normalizeLimit(query.limit);
    46	  const offset = normalizeOffset(query.offset);
    47	  const [data, total] = await repository.list({ email: query.email, limit, offset });
    48	  return paginated(data, total, limit, offset);
    49	}
    50	
    51	export async function updateUser(id: string, input: UpdateUserInput): Promise<User> {
    52	  await getUser(id);
    53	  if (input.email !== undefined) {
    54	    assertValidEmail(input.email);
    55	    const existing = await repository.findByEmail(input.email);
    56	    if (existing && existing.id !== id) {
    57	      throw emailTaken(input.email);
    58	    }
    59	  }
    60	  if (input.name !== undefined) {
    61	    assertValidName(input.name);
    62	  }
    63	  return repository.update(id, input);
    64	}
    65	
